rule sigma "Pass-the-Hash" {
  metadata:
    author = "[Your Name]"
  description: "Detects pass-the-hash attacks"
  tags: "credential_compromise"

  query: (
    process_name = "powershell.exe" and
    process_command_line = "* -NoProfile -NonInteractive -ExecutionPolicy Bypass -Command "*"
  )
}

